edits.before:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};

edits.after:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {
        function isDisabled(date) {
            if (opts.minDate && date < opts.minDate) return true;
            if (opts.maxDate && date > opts.maxDate) return true;
            if (opts.disableWeekends && (date.getDay()===0 || date.getDay()===6)) return true;
            if (opts.disableDayFn && opts.disableDayFn(date)) return true;
            return false;
        }
        function moveDays(dir) {
            var current = self.getDate() || new Date();
            var candidate = new Date(current.getTime());
            while (true) {
                candidate.setDate(candidate.getDate() + dir);
                if (opts.minDate && candidate < opts.minDate) {
                    candidate = new Date(opts.minDate);
                    break;
                }
                if (opts.maxDate && candidate > opts.maxDate) {
                    candidate = new Date(opts.maxDate);
                    break;
                }
                if (!isDisabled(candidate)) {
                    break;
                }
            }
            self.setDate(candidate);
        }

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                moveDays(-1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                moveDays(1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};
